-- Mod-authored era splash painting descriptions, cs_CZ overlay.
-- Baseline in CivVAccess_EraDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_MISSING"] = "Pro tuto éru není k dispozici žádný popis."

CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_CLASSICAL"] =
    "Nejvýše na terasovitém vrcholku kopce stojí velký chrám se sloupy; napravo od něj se stupňovitě svažují menší sloupové síně. Pod nimi stoupají do svahu zahrady, kde se úzká schodiště vinou kolem světlého skalního výběžku zarostlého cypřiši a kvetoucími keři. Veškerý mramor zlatavě a teple září ve slunci."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_MEDIEVAL"] =
    "Zlatá pšeničná pole se vlní pod hradbami obehnaným městečkem se světlými věžemi na kopci. Z jeho cimbuří visí rudé prapory; největší z nich nese černého ptáka s rozepjatými křídly. Je čas žní: shrbení rolníci sbírají posekané obilí, jiní nosí na zádech vysoké snopy a dělníci uprostřed nakládají vůz zapřažený do páru tmavých volů. V horních rozích se do obrazu naklánějí stromy pod jemnou, mlhavou oblohou."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_RENAISSANCE"] =
    "Vysoko nad střechami Florencie stojí Michelangelo na dřevěném žebříku a tesá obrovského bílého mramorového Davida. Samotná hlava a ramena sochy vyplňují levou část obrazu; sochař sahá sotva přes její rameno. Dole se táhnou červené taškové střechy až k velké kupoli florentského dómu a štíhlé zvonici. Za nimi proráží bouřkově tmavou oblohu zlaté světlo."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_INDUSTRIAL"] =
    "V popředí pluje přístavem v New Yorku červenobílý kolesový parník a táhne za sebou kouř ze dvou černých komínů. Na jeho dvou palubách stojí v řadě cestující. Za ním se zeleně tyčí Socha Svobody proti mlhavé jantarové obloze; dál na vodě plují další parníky. Kouř a mlha zbarvují celou scénu do teplých sépiových a zlatých tónů."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_MODERN"] =
    "Divák se dívá ze střechy jednoho mrakodrapu na město plné dalších mrakodrapů. Osvětlené věže ustupují blok za blokem do zlaté mlhy. Hluboko dole se nadzemní dálnice stáčejí v rozlehlé křižovatce, kde po obloucích proudí auta a nákladní vozy. Celý obraz je jednobarevný, zlatý a sépiový jako tónovaná fotografie."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_POSTMODERN"] =
    "Nízké slunce planoucí na konci centrální ulice z poloviny dvacátého století zaplavuje celou ulici zlatým světlem. Muži v oblecích a měkkých kloboucích jdou po pravém chodníku zády k divákovi, kolem markýz a velkého nápisu na vývěsním štítu. U obrubníku stojí nebo kolem projíždějí zakulacené tmavé sedany. Vpředu se budovy rozplývají v oslnivé záři."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_ERADESC_ERA_FUTURE"] =
    "Futuristické město se leskne podél zlatého pobřeží a jeho štíhlé věže ustupují podél břehu do mlhy. Vlevo se nad vodou naklání elegantní červenobílý tryskáč; za ním se přes záliv klene visutý most. V pravém popředí je přímo do mořských útesů zasazen komplex z chromu a skla zakončený kopulí. Na jeho římsách je zeleň; na lávce vyniká osamělá postava."
